<?php $workId=$workId??null;$inputName=$inputName??null;$uploaded=Namira\Db::query($db,'SELECT l.*,a.preview_path,a.bytes,a.mime FROM call_asset_links l JOIN incoming_assets a ON a.id=l.asset_id WHERE l.batch_id=? AND '.($workId?'l.submission_id=?':'l.submission_id IS NULL').' AND l.field_key=? AND l.active=1 ORDER BY l.sequence_no',$workId?[$batch['id'],$workId,$fieldKey]:[$batch['id'],$fieldKey])->fetchAll(); ?>
<div class="call-upload" data-call-uploader data-batch="<?= $batch['id'] ?>" data-work="<?= $workId??0 ?>" data-field="<?= e($fieldKey) ?>" data-input-name="<?= e($inputName??'') ?>" data-formats="<?= e(implode(',',$policy['formats'])) ?>" data-max-bytes="<?= $policy['max_file_mb']*1048576 ?>">
<label class="call-upload-pick"><?= e($label??'فایل‌های این اثر') ?><input type="file" multiple accept="<?= e(implode(',',array_map(fn($x)=>'.'.$x,$policy['formats']))) ?>" data-call-upload></label><small class="hint">هر فایل جداگانه بارگذاری می‌شود؛ اصل فایل تغییر نمی‌کند و فایل ناموفق قابل تلاش مجدد است.</small>
<?php if($inputName): ?><input type="hidden" name="<?= e($inputName) ?>" value=""><?php endif ?>
<div class="call-file-list" data-call-files><?php foreach($uploaded as $file): ?><div class="call-file-row" data-file-link="<?= $file['id'] ?>" data-asset-id="<?= $file['asset_id'] ?>"><?php if($file['preview_path']): ?><img src="<?= e(url('call-file',['id'=>$file['asset_id'],'size'=>'preview'])) ?>" alt="" loading="lazy"><?php endif ?><div><a href="<?= e(url('call-file',['id'=>$file['asset_id']])) ?>"><?= e($file['filename']) ?></a><small><?= fa(round($file['bytes']/1048576,2)) ?> مگابایت · ذخیره شد</small></div><?php if($inputName): ?><input type="hidden" name="<?= e($inputName) ?>[]" value="<?= $file['asset_id'] ?>"><?php endif ?><button type="button" class="outline" data-call-remove-file="<?= $file['id'] ?>">کنار گذاشتن</button></div><?php endforeach ?></div><div data-call-upload-queue></div></div>